174	      analogtv_draw_string_centered(input, &st->ugly_font, localname,
175	                                    xpos, ypos, black_ntsc);
176	    }
177	  }
178	  ypos += (st->ugly_font.char_h * ANALOGTV_SCALE)*5/2;
179	
180	  if (st->logo)
181	    {
182	      int w2 = st->tv->xgwa.width  * 0.2;
183	      int h2 = st->tv->xgwa.height * 0.2;
184	      analogtv_load_ximage (st->tv, input, st->logo, st->logo_mask,
185	                            (st->tv->xgwa.width - w2) / 2,
186	                            st->tv->xgwa.height * 0.28,
187	                            w2, h2);
188	    }
189	
190	  ypos += 58 * ANALOGTV_SCALE;
191	
192	#if 0
193	  analogtv_draw_string_centered(input, &st->ugly_font,
194	                                "Please Stand By", xpos, ypos);
195	  ypos += st->ugly_font.char_h*4;
196	#endif
197	
198	  /* if (! st->colorbars_only_p) */
199	  {
200	    char timestamp[256];
201	    time_t t = time ((time_t *) 0);
202	    struct tm *tm = localtime (&t);
203	
204	    /* Y2K: It is OK for this to use a 2-digit year because it's simulating a
205	       TV display and is purely decorative. */
206	    strftime(timestamp, sizeof(timestamp)-1, "%y.%m.%d %H:%M:%S ", tm);
207	    analogtv_draw_string_centered(input, &st->ugly_font, timestamp,
208	                                  xpos, ypos, black_ntsc);
209	  }
