215	static int
216	getticks(struct state *st)
217	{
218	  struct timeval tv;
219	  gettimeofday(&tv,NULL);
220	  return ((tv.tv_sec - st->basetime.tv_sec)*1000 +
221	          (tv.tv_usec - st->basetime.tv_usec)/1000);
222	}
