225	/* The first time we grab an image, do it the default way.
226	   The second and subsequent times, add "-no-desktop" to the command.
227	   That way we don't have to watch the window un-map 5+ times in a row.
228	   Also, we end up with the desktop on only one channel, and pictures
229	   on all the others (or colorbars, if no imageDirectory is set.)
230	 */
231	static void
232	hack_resources (Display *dpy)
233	{
234	#ifndef HAVE_JWXYZ
235	  static int count = -1;
236	  count++;
237	
238	  if (count == 0)
239	    return;
240	  else if (count == 1)
241	    {
242	      XrmDatabase db = XtDatabase (dpy);
243	      char *res = "desktopGrabber";
