262	static void image_loaded_cb (Screen *screen, Window window, Drawable pixmap,
263	                             const char *name, XRectangle *geometry,
264	                             void *closure)
265	{
266	  /* When an image has just been loaded, store it into the first available
267	     channel.  If there are other unloaded channels, then start loading
268	     another image.
269	  */
270	  struct state *st = (struct state *) closure;
271	  int i;
272	  int this = -1;
273	  int next = -1;
274	
275	  if (!st->image_loading_p) abort();  /* only one at a time... */
276	  st->image_loading_p = False;
277	
278	  for (i = 0; i < MAX_STATIONS; i++) {
279	    if (! st->chansettings[i].image_loaded_p) {
280	      if (this == -1) this = i;
281	      else if (next == -1) next = i;
282	    }
283	  }
284	  if (this == -1) abort();  /* no unloaded stations? */
285	
286	  /* Load this image into the next channel. */
287	  {
288	    analogtv_input *input = st->stations[this];
289	    int width=ANALOGTV_PIC_LEN;
290	    int height=width*3/4;
291	    XImage *image = XGetImage (st->dpy, pixmap, 0, 0,
292	                               width, height, ~0L, ZPixmap);
293	    XFreePixmap(st->dpy, pixmap);
294	
295	    analogtv_setup_sync(input, 1, (random()%20)==0);
296	    analogtv_load_ximage(st->tv, input, image, 0, 0, 0, 0, 0);
297	    if (image) XDestroyImage(image);
298	    st->chansettings[this].image_loaded_p = True;
299	#if 0
300	    if (name) {
301	      const char *s = strrchr (name, '/');
302	      if (s) s++;
303	      else s = name;
304	      st->chansettings[this].filename = strdup (s);
305	    }
306	    fprintf(stderr, "%s: loaded channel %d, %s\n", progname, this, 
307	            st->chansettings[this].filename);
308	#endif
309	  }
310	
311	  /* If there are still unloaded stations, fire off another loader. */
312	  if (next != -1)
313	    analogtv_load_random_image (st);
314	}
