317	/* Queues a single image for loading.  Only load one at a time.
318	   The image is done loading when st->img_loader is null and
319	   it->loaded_image is a pixmap.
320	 */
321	static void
322	analogtv_load_random_image(struct state *st)
323	{
324	  int width=ANALOGTV_PIC_LEN;
325	  int height=width*3/4;
326	  Pixmap p;
327	
328	  if (st->image_loading_p)  /* a load is already in progress */
329	    return;
330	
331	  st->image_loading_p = True;
332	  p = XCreatePixmap(st->dpy, st->window, width, height, st->tv->visdepth);
333	  hack_resources(st->dpy);
334	  load_image_async (st->tv->xgwa.screen, st->window, p, image_loaded_cb, st);
335	}
