536	static unsigned long
537	xanalogtv_draw (Display *dpy, Window window, void *closure)
538	{
539	  struct state *st = (struct state *) closure;
540	  int i;
541	
542	  int curticks=getticks(st);
543	  double curtime=curticks*0.001;
544	
545	  const analogtv_reception *recs[MAX_MULTICHAN];
546	  unsigned rec_count = 0;
547	
548	  int auto_change = curticks >= st->change_ticks && st->tv->powerup > 10.0 ? 1 : 0;
549	
550	  if (st->change_now || auto_change) {
551	    st->curinputi=(st->curinputi+st->change_now+auto_change+N_CHANNELS)%N_CHANNELS;
552	    st->change_now = 0;
553	    st->cs = &st->chansettings[st->curinputi];
554	#if 0
555	    fprintf (stderr, "%s: channel %d, %s\n", progname, st->curinputi,
556	             st->cs->filename);
557	#endif
558	    st->change_ticks = curticks + st->cs->dur;
559	    /* Set channel change noise flag */
560	    st->tv->channel_change_cycles=200000;
561	  }
562	
563	  for (i=0; i<MAX_MULTICHAN; i++) {
564	    analogtv_reception *rec = &st->cs->recs[i];
565	    analogtv_input *inp=rec->input;
566	    if (!inp) continue;
567	
568	    if (inp->updater) {
569	      inp->next_update_time = curtime;
570	      (inp->updater)(inp);
571	    }
572	    rec->ofs += rec->freqerr;
573	  }
574	
575	  st->tv->powerup=curtime;
576	
577	  for (i=0; i<MAX_MULTICHAN; i++) {
578	    analogtv_reception *rec = &st->cs->recs[i];
579	    if (rec->input) {
580	      analogtv_reception_update(rec);
581	      recs[rec_count] = rec;
582	      ++rec_count;
583	    }
584	  }
585	  analogtv_draw(st->tv, st->cs->noise_level, recs, rec_count);
586	
587	#ifdef HAVE_MOBILE
588	  return 0;
589	#else
590	  return 5000;
591	#endif
592	}
