602	static Bool
603	xanalogtv_event (Display *dpy, Window window, void *closure, XEvent *event)
604	{
605	  struct state *st = (struct state *) closure;
606	
607	  if (event->type == ButtonPress)
608	    {
609	      unsigned button = event->xbutton.button;
610	      st->change_now = button == 2 || button == 3 || button == 5 ? -1 : 1;
611	      return True;
612	    }
613	  else if (event->type == KeyPress)
614	    {
615	      KeySym keysym;
616	      char c = 0;
617	      XLookupString (&event->xkey, &c, 1, &keysym, 0);
618	      if (c == ' ' || c == '\t' || c == '\r' || c == '\n' ||
619	          keysym == XK_Up || keysym == XK_Right || keysym == XK_Prior)
620	        {
621	          st->change_now = 1;
622	          return True;
623	        }
624	      else if (c == '\b' ||
625	               keysym == XK_Down || keysym == XK_Left || keysym == XK_Next)
626	        {
627	          st->change_now = -1;
628	          return True;
629	        }
630	      else if (screenhack_event_helper (dpy, window, event))
631	        goto DEF;
632	    }
633	  else if (screenhack_event_helper (dpy, window, event))
634	    {
635	    DEF:
636	      st->change_now = ((random() & 1) ? 1 : -1);
637	      return True;
638	    }
639	
640	  return False;
641	}
