 * view is full of them. */
void test_the_picture_fills_the_view_once_the_clock_has_run_the_power_up(void) {
  void *st = xanalogtv_hack.init(dpy, XSHIM_WINDOW);
  int inside = 0, outside = 0;
  for (int i = 0; i < 40; i++) {
