static void xanalogtv_free(Display *dpy, Window window, void *closure) {
  if (xanalogtv_pending.done) {
    XFreePixmap(dpy, xanalogtv_pending.target);
    xanalogtv_pending.done = NULL;
  }
  xanalogtv_free_upstream(dpy, window, closure);
}

